using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "SampleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 renamed the default discriminator property
        // from "Discriminator" to "$type". Existing documents use the old name,
        // so we must explicitly preserve it.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change: EF Core 9 no longer embeds the discriminator in the
        // JSON "id" property. Existing documents have id = "Session|<key>",
        // so we must preserve the old compound format.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);

        modelBuilder.Entity<Session>().ToContainer("Sessions");
        modelBuilder.Entity<Session>().HasPartitionKey(s => s.TenantId);
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string TenantId { get; set; } = string.Empty;
    public string UserName { get; set; } = string.Empty;
}

using Microsoft.EntityFrameworkCore;

class CosmosService
{
    // Breaking change: EF Core 9 Cosmos provider no longer supports synchronous
    // I/O — calling SaveChanges(), ToList(), First(), etc. now throws.
    // All calls must use async equivalents.

    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        // Before (EF Core 8 — sync was allowed):
        //   return db.Sessions.Where(s => s.TenantId == "tenant1").ToList();

        // After (EF Core 9 — must use async):
        return await db.Sessions
            .Where(s => s.TenantId == "tenant1")
            .ToListAsync();
    }

    async Task AddSessionAsync(CosmosDbContext db, Session session)
    {
        // Before (EF Core 8):
        //   db.Sessions.Add(session);
        //   db.SaveChanges();

        // After (EF Core 9):
        db.Sessions.Add(session);
        await db.SaveChangesAsync();
    }
}

